var e={kind:`dp`,caption:`n = 6（爬到第 6 阶有多少种走法）`,rowLabels:[`走法数`],colLabels:[`第 1 阶`,`第 2 阶`,`第 3 阶`,`第 4 阶`,`第 5 阶`,`第 6 阶`],frames:[{step:0,note:`先看边界：n ≤ 2 时直接返回 n。这里 n = 6，得往下推 —— 不过 n ≤ 2 的答案正好就是推导的起点：第 1 阶 1 种，第 2 阶 2 种（1+1 或 2）。`,values:{},focus:null,deps:[],state:{},marks:{},band:null,aux:null,out:null},{step:1,note:`a = 1 记第 1 阶的走法数，b = 2 记第 2 阶的走法数。接下来要算第 3 阶。`,values:{"0,0":`1`,"0,1":`2`},focus:null,deps:[],state:{},marks:{a:{r:0,c:0},b:{r:0,c:1}},band:null,aux:null,out:null},{step:2,note:`第 3 阶只可能从第 2 阶跨 1 步、或从第 1 阶跨 2 步上来，没有别的走法。所以第 3 阶 = a + b = 1 + 2 = 3。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`},focus:{r:0,c:2},deps:[{r:0,c:0},{r:0,c:1}],state:{},marks:{a:{r:0,c:0},b:{r:0,c:1}},band:null,aux:null,out:`第 3 阶 = 3`},{step:3,note:`窗口整体往前挪一格：a 接过旧的 b（第 2 阶 = 2），b 变成刚算出的 3。Python 的 a, b = b, a + b 是右边先用旧值算完再一起赋值，所以不会互相污染。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`},focus:null,deps:[],state:{},marks:{a:{r:0,c:1},b:{r:0,c:2}},band:null,aux:null,out:`第 3 阶 = 3`},{step:2,note:`第 4 阶只可能从第 3 阶跨 1 步、或从第 2 阶跨 2 步上来，没有别的走法。所以第 4 阶 = a + b = 2 + 3 = 5。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`},focus:{r:0,c:3},deps:[{r:0,c:1},{r:0,c:2}],state:{},marks:{a:{r:0,c:1},b:{r:0,c:2}},band:null,aux:null,out:`第 4 阶 = 5`},{step:3,note:`窗口整体往前挪一格：a 接过旧的 b（第 3 阶 = 3），b 变成刚算出的 5。Python 的 a, b = b, a + b 是右边先用旧值算完再一起赋值，所以不会互相污染。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`},focus:null,deps:[],state:{},marks:{a:{r:0,c:2},b:{r:0,c:3}},band:null,aux:null,out:`第 4 阶 = 5`},{step:2,note:`第 5 阶只可能从第 4 阶跨 1 步、或从第 3 阶跨 2 步上来，没有别的走法。所以第 5 阶 = a + b = 3 + 5 = 8。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`,"0,4":`8`},focus:{r:0,c:4},deps:[{r:0,c:2},{r:0,c:3}],state:{},marks:{a:{r:0,c:2},b:{r:0,c:3}},band:null,aux:null,out:`第 5 阶 = 8`},{step:3,note:`窗口整体往前挪一格：a 接过旧的 b（第 4 阶 = 5），b 变成刚算出的 8。Python 的 a, b = b, a + b 是右边先用旧值算完再一起赋值，所以不会互相污染。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`,"0,4":`8`},focus:null,deps:[],state:{},marks:{a:{r:0,c:3},b:{r:0,c:4}},band:null,aux:null,out:`第 5 阶 = 8`},{step:2,note:`第 6 阶只可能从第 5 阶跨 1 步、或从第 4 阶跨 2 步上来，没有别的走法。所以第 6 阶 = a + b = 5 + 8 = 13。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`,"0,4":`8`,"0,5":`13`},focus:{r:0,c:5},deps:[{r:0,c:3},{r:0,c:4}],state:{},marks:{a:{r:0,c:3},b:{r:0,c:4}},band:null,aux:null,out:`第 6 阶 = 13`},{step:3,note:`窗口整体往前挪一格：a 接过旧的 b（第 5 阶 = 8），b 变成刚算出的 13。Python 的 a, b = b, a + b 是右边先用旧值算完再一起赋值，所以不会互相污染。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`,"0,4":`8`,"0,5":`13`},focus:null,deps:[],state:{},marks:{a:{r:0,c:4},b:{r:0,c:5}},band:null,aux:null,out:`第 6 阶 = 13`},{step:5,note:`循环结束，b 就是到第 6 阶的走法数：13。注意整个过程只用了两个变量 —— 上面这张表是画给你看的，代码从头到尾只握着 a 和 b。`,values:{"0,0":`1`,"0,1":`2`,"0,2":`3`,"0,3":`5`,"0,4":`8`,"0,5":`13`},focus:null,deps:[],state:{"0,5":`hit`},marks:{b:{r:0,c:5}},band:null,aux:null,out:`返回 13`}]};export{e as default};